import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.DBKUV7en.js";const b=JSON.parse('{"title":"付録. この教科書で使う主な研究","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/studies.md","filePath":"appendix/studies.md","lastUpdated":null}'),i={name:"appendix/studies.md"};function s(l,t,n,o,h,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="付録-この教科書で使う主な研究" tabindex="-1">付録. この教科書で使う主な研究 <a class="header-anchor" href="#付録-この教科書で使う主な研究" aria-label="Permalink to &quot;付録. この教科書で使う主な研究&quot;">​</a></h1><p>この教科書で使っている研究を、1か所にまとめました。各回では「条件は付録へ」と書くだけにしています。どの研究も、豆1種類などの狭い条件が中心なので、自分の豆と淹れ方にそのまま当てはまるとは限りません。</p><h2 id="「一番」と言うときの約束" tabindex="-1">「一番」と言うときの約束 <a class="header-anchor" href="#「一番」と言うときの約束" aria-label="Permalink to &quot;「一番」と言うときの約束&quot;">​</a></h2><p>僕は、比べた相手を書かずに「一番」とは言わないことにしています。使うのは、次の2つの言い方だけです。</p><ul><li>抽出の中では、濃度と抽出率を比べると、濃度の効き方が大きかった(ドリップ、豆1種類、2020年)</li><li>浸漬の研究では、焙煎度は湯温や時間より大きく効いた。挽き目や比率とは比べていない(豆1種類のブレンド、焙煎2段階、2024年)</li></ul><p>素材と抽出の効き方を、同じ実験で大きさまで比べた研究は、見つかっていません。合言葉の「個性は素材で決まり、ブレは抽出で起きる」は、研究の結論ではなく、僕の考察です。</p><h2 id="一覧-何と何を比べたか" tabindex="-1">一覧: 何と何を比べたか <a class="header-anchor" href="#一覧-何と何を比べたか" aria-label="Permalink to &quot;一覧: 何と何を比べたか&quot;">​</a></h2><table tabindex="0"><thead><tr><th>研究</th><th>方式</th><th>比べた相手</th><th>使う回</th></tr></thead><tbody><tr><td>Batali 2020</td><td>透過</td><td>湯温(87/90/93℃)。濃度と抽出率はそろえた。濃度・抽出率の効き方も分析</td><td>第3・4・6回</td></tr><tr><td>Frost 2020</td><td>透過</td><td>濃度 × 抽出率 × 焙煎度3段階</td><td>第4回</td></tr><tr><td>Cotter 2021</td><td>透過</td><td>湯温 × 濃度 × 抽出率(27通り)への、消費者の好み</td><td>第4回</td></tr><tr><td>Guinard 2023</td><td>上の3つの統合</td><td>濃度・抽出率と、好みのグループ</td><td>第4回</td></tr><tr><td>Liang 2021</td><td>浸漬</td><td>比率・挽き目・焙煎度・湯温と、抽出率・濃度</td><td>第1回</td></tr><tr><td>Batali 2022</td><td>浸漬(水出し含む)</td><td>産地3種 × 焙煎3段階 × 抽出温度(4/22/92℃)</td><td>第1回、第18回</td></tr><tr><td>Liang 2024</td><td>浸漬</td><td>焙煎度 × 湯温 × 時間</td><td>第6・8回</td></tr><tr><td>Rune 2023</td><td>浸漬(フレンチプレス)</td><td>焙煎度ごとの酸の量。酸の種類の聞き分け</td><td>第3・8回</td></tr><tr><td>Lindsey 2024</td><td>浸漬主体(エアロプレス)</td><td>焙煎度5段階 × 抽出時間</td><td>第6・8回、カフェイン付録</td></tr><tr><td>Frost 2019</td><td>透過</td><td>ドリッパーの形 × 挽き目 × 焙煎度</td><td>第17回</td></tr><tr><td>Batali 2021(ポスター)</td><td>保存の実験</td><td>保存容器3種 × 時間(最大3時間)</td><td>第20回</td></tr><tr><td>Hendon 2014</td><td>計算のみ</td><td>水のミネラルの種類</td><td>第15回</td></tr><tr><td>Lee 2023</td><td>数式モデル</td><td>挽き目と水の通り道</td><td>第7回</td></tr></tbody></table><h2 id="研究ごとの中身" tabindex="-1">研究ごとの中身 <a class="header-anchor" href="#研究ごとの中身" aria-label="Permalink to &quot;研究ごとの中身&quot;">​</a></h2><h3 id="batali-ら-2020" tabindex="-1">Batali ら 2020 <a class="header-anchor" href="#batali-ら-2020" aria-label="Permalink to &quot;Batali ら 2020&quot;">​</a></h3><p>UC Davis のチームが、業務用ドリップ機(Curtis G4、紙フィルター)で、ホンジュラス産ウォッシュドを淹れました。焙煎度は論文に書かれていません。訓練を受けた12人が、湯温87/90/93℃、濃度約1.0〜1.5%、抽出率約16〜24%の9パターンを、65℃で評価しています。</p><p>濃度が上がると、苦さ、渋さ、口当たりの重さ、酸っぱさが強まりました。抽出率が上がると、酸っぱさが弱まり、紅茶っぽさが強まりました。効き方は濃度のほうが大きく、濃度と抽出率をそろえると、湯温の影響は小さい結果でした。限界は、豆1種類、ドリップのみ、抽出後約30分置いて提供したこと、水の偏りによるばらつきです。味の項目数は、本文では31、Guinard 2023 のまとめでは33と、数え方が違います。</p><h3 id="frost-ら-2020" tabindex="-1">Frost ら 2020 <a class="header-anchor" href="#frost-ら-2020" aria-label="Permalink to &quot;Frost ら 2020&quot;">​</a></h3><p>同じ Curtis で、濃度(1/1.25/1.5%)、抽出率(16/20/24%)、焙煎度3段階を組み合わせ、訓練パネルが30項目を評価しました。苦さは、濃度と抽出率の両方で増える傾向でした。Batali 2020 では抽出率と苦さに有意な関係がなく、食い違っています。人数と豆の産地は、確認できていません。論文本体は未読で、SCA の解説記事と Guinard 2023 のまとめで確認しました。</p><h3 id="cotter-ら-2021" tabindex="-1">Cotter ら 2021 <a class="header-anchor" href="#cotter-ら-2021" aria-label="Permalink to &quot;Cotter ら 2021&quot;">​</a></h3><p>中煎りのホンジュラス産ウォッシュドを、湯温、濃度、抽出率の27通りで淹れて、118人の消費者(主に大学生年代)が飲みました。27通り × 118人で、3,186回の試飲です。好みは2つのグループに分かれ、違いは主に濃度で出ました。酸味と全体の濃度が、好みを大きく左右しています。北カリフォルニアの若い成人で、要旨だけ確認しました。</p><h3 id="guinard-ら-2023" tabindex="-1">Guinard ら 2023 <a class="header-anchor" href="#guinard-ら-2023" aria-label="Permalink to &quot;Guinard ら 2023&quot;">​</a></h3><p>上の3つ(Frost 2020、Batali 2020、Cotter 2021)をまとめた研究です。化学・物理の測定が324、訓練パネルの評価が32,076、消費者の評価が3,186。多数派の57%は、濃度が低いほど好んで、抽出率18%付近で最大でした。少数派の43%は、低い抽出率で中〜高い濃度と、高い抽出率で中くらいの濃度の、両方が好きでした。全体の平均は古い目安に近く出ますが、2グループを混ぜた平均です。北カリフォルニアの若い成人、豆1種類、ドリップのみで、著者も別の地域では別のグループになりうると述べています。</p><h3 id="liang-ら-2021" tabindex="-1">Liang ら 2021 <a class="header-anchor" href="#liang-ら-2021" aria-label="Permalink to &quot;Liang ら 2021&quot;">​</a></h3><p>浸漬で、比率、挽き目、焙煎度、湯温(80〜99℃)と、抽出率・濃度の関係を調べました。時間が十分たつと、抽出率は約21%で、比率に関係なくほぼ一定でした。濃度は、湯と粉の比率にほぼ反比例します。平衡に達した場合の話です。</p><h3 id="batali-ら-2022" tabindex="-1">Batali ら 2022 <a class="header-anchor" href="#batali-ら-2022" aria-label="Permalink to &quot;Batali ら 2022&quot;">​</a></h3><p>浸漬(水出しを含む)で、産地3種(ウォッシュド、ハニー、ウェットハル)、焙煎3段階、抽出温度4/22/92℃を比べました。平衡まで抽出して、濃度をTDS 2%にそろえ、4℃で飲んでいます。92℃は苦さ、酸っぱさ、ゴム臭が強く、4℃と22℃は花の香りが強い傾向でした。産地や焙煎との組み合わせで変わります。4℃と22℃の差は小さく、焙煎度と産地のほうが、抽出温度より影響が大きい結果でした。Toddy 社の資金提供があります。</p><h3 id="liang-ら-2024" tabindex="-1">Liang ら 2024 <a class="header-anchor" href="#liang-ら-2024" aria-label="Permalink to &quot;Liang ら 2024&quot;">​</a></h3><p>浸漬で、焙煎度、湯温、時間を比べています。エルサルバドルとニカラグアのブレンドを、浅煎りと中深煎りに焙煎して、14人が評価しました。味を変えた順は、焙煎度、湯温、時間です。浅煎りは酸っぱさ、柑橘、ベリー、フルーティ。深煎りは苦さ、焦げ、スモーキー、ココア。高温は苦さと渋さが増え、低温は甘さが増えました。甘さは濃度と逆向きに動き、ほかの19項目は濃度と同じ向きです。</p><p>豆1種類、焙煎2段階で、薄めて一晩冷蔵してから飲んでいます。温度は4/22/92℃で、原文で確認しました。同じ温度の組み方を使う別の研究(Batali 2022)とは、別の研究です。</p><h3 id="rune-ら-2023" tabindex="-1">Rune ら 2023 <a class="header-anchor" href="#rune-ら-2023" aria-label="Permalink to &quot;Rune ら 2023&quot;">​</a></h3><p>アラビカ5種(ブラジル2、ボリビア1、ケニア2)を浅め、中、深めに焙煎して、フレンチプレスで淹れ、成分を測りました。焙煎が進むと、クロロゲン酸、クエン酸、リンゴ酸と、糖が減りました。キナ酸と酢酸などは増えています。訓練していない40人の試験では、コーヒーに入っている程度の濃度で区別できた酸は、クエン酸だけでした。専門家13人でも、足した酸の種類を当てた人はいません。産地ごとに、酸の量に一貫した違いもありませんでした。</p><h3 id="lindsey-ら-2024" tabindex="-1">Lindsey ら 2024 <a class="header-anchor" href="#lindsey-ら-2024" aria-label="Permalink to &quot;Lindsey ら 2024&quot;">​</a></h3><p>エチオピアのナチュラルとウォッシュドを5段階に焙煎し、エアロプレス(湯:粉=15:1)で1/2/10分抽出しました。焙煎が進むと孔は増え、クロロゲン酸は大きく減ります。質量減少が約12〜14%を超えると、抽出率が下がる傾向でした。ウォッシュドの最も浅い2つ(未発達とされる範囲)は、少し抽出率が低くなっています。豆2種で、味は測っていません。</p><h3 id="frost-ら-2019" tabindex="-1">Frost ら 2019 <a class="header-anchor" href="#frost-ら-2019" aria-label="Permalink to &quot;Frost ら 2019&quot;">​</a></h3><p>業務用ドリップ機で、バスケットの形(平底と半円すい)、挽き目、焙煎度を比べました。非専門家45人の三点比較では、形の違いを25人が当てました(偶然なら15人)。挽き目の違い(粒の大きさで約25%差)は、当たりませんでした。訓練パネル12人の評価では、違いの大きさは焙煎度、形の順です。浅煎りでは、平底が甘さ、花、ドライフルーツ、半円すいが柑橘、酸っぱさでした。家庭の手淹れで同じかは、分かっていません。SCA の記事で確認し、論文本文は未読です。</p><h3 id="batali-ら-2021-asic-のポスター" tabindex="-1">Batali ら 2021(ASIC のポスター) <a class="header-anchor" href="#batali-ら-2021-asic-のポスター" aria-label="Permalink to &quot;Batali ら 2021(ASIC のポスター)&quot;">​</a></h3><p>3種類の豆を、真空断熱ポット、保温ジャケットのポット、ホットプレートの上のガラスに、最大3時間置きました。保温しない断熱ポットのほうが、品質を保てています。浅煎りは、時間とともに酸っぱさと柑橘が弱まり、ロースト感が強まりました。査読論文ではなく学会のポスターで、人数などは確認していません。</p><h3 id="hendon-ら-2014" tabindex="-1">Hendon ら 2014 <a class="header-anchor" href="#hendon-ら-2014" aria-label="Permalink to &quot;Hendon ら 2014&quot;">​</a></h3><p>実際には淹れず、Na、Mg、Ca のイオンがコーヒーの成分と結びつく強さを計算した研究です。「マグネシウムがよく溶かす」などは報道の言い方で、要旨では確認できていません。官能試験ではなく、本文も未読です。</p><h3 id="lee、smith、arshad-2023" tabindex="-1">Lee、Smith、Arshad 2023 <a class="header-anchor" href="#lee、smith、arshad-2023" aria-label="Permalink to &quot;Lee、Smith、Arshad 2023&quot;">​</a></h3><p>水の通り道が2本だけの、単純な数式モデルです。ある細かさを超えると、水が通りやすい所と通りにくい所の差が広がって、かえって抽出率が下がることを示しました。味は測っておらず、arXiv 版の要旨まで確認しています。</p><h3 id="そのほか" tabindex="-1">そのほか <a class="header-anchor" href="#そのほか" aria-label="Permalink to &quot;そのほか&quot;">​</a></h3><p>本文で使っている資料を、表にまとめます。</p><table tabindex="0"><thead><tr><th>資料</th><th>使う回</th></tr></thead><tbody><tr><td>Moroney ら 2019(粉の層の流れのモデル)</td><td>第1・2回</td></tr><tr><td>Colonna-Dashwood ら 2016(冷やして挽く)</td><td>第11回</td></tr><tr><td>Royal Coffee 2017(焙煎度と抽出率の社内データ)</td><td>第6回</td></tr><tr><td>Royal Coffee 2018(水の社内試飲)</td><td>第15回</td></tr><tr><td>Barista Hustle フォーラム(注ぐ高さ・撹拌)</td><td>第5・7回</td></tr></tbody></table><h2 id="確かさの一覧" tabindex="-1">確かさの一覧 <a class="header-anchor" href="#確かさの一覧" aria-label="Permalink to &quot;確かさの一覧&quot;">​</a></h2><details class="details custom-block"><summary>表を開く</summary><table tabindex="0"><thead><tr><th>研究</th><th>原文の確認</th><th>確かさ</th></tr></thead><tbody><tr><td>Batali 2020</td><td>原文を確認</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span></td></tr><tr><td>Frost 2020</td><td>論文は未読。SCA の記事と Guinard 2023 で確認</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span></td></tr><tr><td>Cotter 2021</td><td>要旨のみ(本文は有料)</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span></td></tr><tr><td>Guinard 2023</td><td>原文を確認(オープンアクセス)</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span></td></tr><tr><td>Liang 2021</td><td>原文を確認</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span></td></tr><tr><td>Batali 2022</td><td>原文を確認</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span></td></tr><tr><td>Liang 2024</td><td>原文を確認(温度は4/22/92℃)</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span></td></tr><tr><td>Rune 2023</td><td>原文を確認</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span></td></tr><tr><td>Lindsey 2024</td><td>原文を確認</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span></td></tr><tr><td>Frost 2019</td><td>SCA の記事で確認。論文本文は未読</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span></td></tr><tr><td>Batali 2021 ポスター</td><td>ポスターを確認</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> 査読論文ではない。人数は <span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span></td></tr><tr><td>Hendon 2014</td><td>要旨まで</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> 計算のみ</td></tr><tr><td>Lee 2023</td><td>要旨まで(arXiv)</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> モデル研究。味は測っていない</td></tr><tr><td>Moroney 2019</td><td>原文を確認</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> モデル研究</td></tr><tr><td>Colonna-Dashwood 2016</td><td>書誌のみ確認</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> 味は測っていない</td></tr><tr><td>Royal Coffee の社内データ</td><td>記事を確認</td><td><span class="stamp stamp-shop ignore-header" tabindex="0" data-tip="お店やメーカーの説明。参考になるけれど、宣伝を含むこともある" aria-label="店の説明: お店やメーカーの説明。参考になるけれど、宣伝を含むこともある">店の説明</span> 管理された研究ではない</td></tr><tr><td>Barista Hustle フォーラム</td><td>投稿を確認</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> 数字は未確認</td></tr></tbody></table></details><h2 id="出典" tabindex="-1">出典 <a class="header-anchor" href="#出典" aria-label="Permalink to &quot;出典&quot;">​</a></h2><ul><li>Batali ら 2020: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC7536440/" target="_blank" rel="noreferrer">PMC7536440</a></li><li>Guinard ら 2023: <a href="https://ift.onlinelibrary.wiley.com/doi/full/10.1111/1750-3841.16531" target="_blank" rel="noreferrer">Wiley</a></li><li>Cotter ら 2021: <a href="https://ift.onlinelibrary.wiley.com/doi/10.1111/1750-3841.15561" target="_blank" rel="noreferrer">Wiley</a></li><li>Frost ら 2020 の解説: <a href="https://sca.coffee/sca-news/25/issue-13/towards-a-new-brewing-chart-xpj8t" target="_blank" rel="noreferrer">SCA</a></li><li>Liang ら 2021: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC7994670/" target="_blank" rel="noreferrer">PMC7994670</a></li><li>Batali ら 2022: <a href="https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9407127/" target="_blank" rel="noreferrer">PMC9407127</a></li><li>Liang ら 2024: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11335879/" target="_blank" rel="noreferrer">PMC11335879</a></li><li>Rune ら 2023: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10074501" target="_blank" rel="noreferrer">PMC10074501</a></li><li>Lindsey ら 2024: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11586412/" target="_blank" rel="noreferrer">PMC11586412</a></li><li>Frost ら 2019: <a href="https://sca.coffee/sca-news/25-magazine/issue-8/english/flat-vs-cone-basket-shape-is-as-important-as-grind-size-in-drip-brew-coffee-25-magazine-issue-8-lpgsg" target="_blank" rel="noreferrer">SCA 25 Magazine</a></li><li>Batali ら 2021 のポスター: <a href="https://alphavisa.com/asic/2021/documents/eposters/S8-P-02_5066_BATALI.pdf" target="_blank" rel="noreferrer">PDF</a></li><li>Lee ら 2023: <a href="https://arxiv.org/abs/2206.12373" target="_blank" rel="noreferrer">arXiv</a></li><li>Moroney ら 2019: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6668809/" target="_blank" rel="noreferrer">PMC6668809</a></li></ul><p>次は、<a href="/coffee-textbook/glossary">用語集</a>で言葉を確かめてみてください。</p>',45)])])}const m=a(i,[["render",s]]);export{b as __pageData,m as default};
